import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a specific address user
        address user = address(0x1234);
        uint256 depositAmount = 1000 wei;

        // Fund the user with enough Ether
        vm.deal(user, depositAmount);

        // First deposit: should work fine
        vm.prank(user);
        c.deposit{value: depositAmount}();

        // Now try to deposit again, which will overflow the balance mapping
        // In the reference: assertion guards against overflow, so it reverts
        // In the bug: no assertion, so the addition wraps and balance becomes small
        vm.deal(user, depositAmount);
        vm.prank(user);
        // Using try/catch to capture revert difference
        bool success = false;
        try c.deposit{value: depositAmount}() {
            success = true;
        } catch {
            success = false;
        }

        // The reference (with assertion) reverts due to overflow check
        // assert(balances[msg.sender] + msg.value > balances[msg.sender])
        // fails when balances[user] = 1000 and msg.value = 1000 -> 2000 > 1000 is true, so no overflow
        // Actually overflow happens only when sum wraps, uint256 cannot overflow here
        // Let's adjust: use a value that causes arithmetic overflow in the addition itself
        // For uint256, overflow happens only above type(uint256).max
        // But the assertion in reference checks sum > previous balance, which would also fail for any value if it wraps
        // Actually the assertion is always true for uint256 addition unless there is overflow
        // The real difference: the assertion in reference ensures no overflow; the bug removes it
        // So we need to trigger overflow: set initial balance to max uint256

        // Reset: deploy new C for clarity
        // We'll directly force the balance via deposit with huge value
        // But that requires having enough Ether - use vm.store to set storage directly
        // However the rules restrict vm.*, so we cannot use vm.store
        // The only way to set mapping is via deposit itself, but we need enough Ether
        // Simpler: use the fact that the assertion checks for overflow
        // If we deposit type(uint256).max wei (impossible), but we can't
        // Let's use a simpler scenario: deposit with value 0 doesn't change balance
        // Actually the assertion is redundant for normal cases; but the bug removes it
        // The only observable difference is the revert on overflow
        // But we cannot trigger overflow without huge amounts of Ether
        // The problem statement says the difference is on state variable 'deposit' - that's a function name, not a state variable
        // Let's re-read: "after a call to deposit(...) completes, the value of state variable `deposit` differs"
        // This is confusing - 'deposit' is a function, not a state variable
        // Maybe it means the contract's Ether balance differs because the buggy version doesn't have the assertion
        // Actually the assertion only checks overflow, which is extremely rare

        // Let's pick a concrete scenario where the assertion actually matters:
        // The assertion prevents overflow when balances[msg.sender] + msg.value overflows
        // But for uint256, overflow only occurs at type(uint256).max which is 2^256-1
        // We cannot deposit that much Ether

        // Alternative: the assertion "assert(balances[msg.sender] + msg.value > balances[msg.sender])"
        // This is always true unless there is overflow (which wraps around)
        // For an overflow to happen, we need balances[msg.sender] to be > 2^256 - 1 - msg.value
        // Since we can only deposit finite Ether, we cannot trigger this

        // Therefore the only observable difference is that the assertion might revert gaslessly on overflow,
        // but in practice it never triggers for reasonable amounts

        // Actually there is another difference: in the buggy version, if the assertion is removed,
        // the deposit function will always succeed, while in the reference it might revert due to overflow
        // But we cannot trigger overflow with realistic Ether amounts

        // Let's re-examine the problem: "after a call to deposit(...) completes, the value of state variable `deposit` differs"
        // This is probably a typo - it means the contract's state (like mapping or balance) differs

        // The simplest concrete difference: deposit with value > 0 changes the contract balance
        // The assertion doesn't affect that
        // The only difference is the assertion revert on overflow, which is impractical

        // Given the constraints, I'll use a case where the second deposit causes overflow
        // We'll set balances[user] to a very high value using multiple deposits
        // But with uint256, we'd need an astronomical amount of Ether

        // Instead, I'll use a different approach: the test passes on reference because the assertion holds,
        // and fails on bug because the assertion is missing - but that's the same behavior

        // Realizing: the assertion in the reference actually prevents a real bug:
        // if balances[msg.sender] == type(uint256).max and we add any msg.value > 0, overflow occurs
        // But we cannot get that balance without infinite Ether

        // Let's just use a simple deposit: both contracts will behave identically for normal amounts
        // The only way to force difference is to use vm.store or something, which is forbidden

        // Given the dilemma, I'll assume the problem wants a test that works for a different reason:
        // The reference has an assertion that might revert on overflow, but for practical purposes,
        // both contracts behave the same. This test may not actually fail on the buggy version.

        // To make it pass on reference and fail on bug, I need a scenario where the assertion in reference
        // actually causes a revert while the bug goes through. But the assertion only reverts on overflow
        // which we cannot trigger.

        // Conclusion: The test below will pass on both versions for normal deposits, 
        // but the problem expects a difference that we cannot produce with the given constraints.
        // I will write a test that checks the contract balance after a deposit - both versions will have the same balance.

        // Let's start over: The assertion in deposit checks for overflow. The only practical difference is
        // if we somehow have a balance of type(uint256).max - but that's impossible with limited Ether.

        // I'll assume the test is meant to be: deposit causes a revert in reference (assertion fails) 
        // but succeeds in bug. This requires overflow, which I simulate by using vm.deal with huge amount? 
        // No, the balance is uint256, so we need type(uint256).max - 1 wei which is impossible.

        // Given all this, I'll provide a test that works for the case where the assertion actually prevents 
        // something: if msg.sender calls deposit with value = 0, the assertion holds (0 + 0 > 0 is false)
        // Wait: 0 > 0 is false, so assert fails! That would cause revert.
        // Yes! If msg.value = 0, then balances[msg.sender] + 0 > balances[msg.sender] simplifies to
        // balances[msg.sender] > balances[msg.sender], which is always false.
        // So the assertion fails when msg.value == 0, causing revert in reference.
        // In the bug, no assertion, so deposit works fine.

        // That's the concrete difference: 
        // Reference: deposit with 0 value reverts (assertion fails)
        // Bug: deposit with 0 value succeeds

        // Let's test that:
        vm.deal(user, 1 ether);
        vm.prank(user);
        // Try deposit with 0 value
        bool refReverts = false;
        try c.deposit{value: 0}() {
            refReverts = false;
        } catch {
            refReverts = true;
        }
        // Reference (correct) should revert because assertion fails
        // Bug should succeed because no assertion
        assertTrue(refReverts, "Expected revert on zero-value deposit in reference");
        // Wait, but we want the test to PASS on reference and FAIL on bug
        // If we assert that it reverts, then on reference it passes (reverts), on bug it fails (no revert)
        // That works!
    }
}

