pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address payable alice = payable(address(0x1234));
        address payable bob = payable(address(0x5678));
        // Fund alice
        vm.deal(alice, 1 ether);
        // alice deposits 1 wei
        vm.prank(alice);
        c.deposit{value: 1 wei}();
        // deploy a contract that rejects all incoming Ether
        Rejector rej = new Rejector();
        // creator (default msg.sender from setUp) calls migrateTo to the rejector
        c.migrateTo(address(rej));
        // In the reference (.transfer), the transfer reverts, so contract balance stays 1 wei.
        // In the mutant (.call), the call succeeds (Ether sent, rejector reverts silently) and contract balance becomes 0.
        bool eq = address(c).balance == 1 wei;
        assertTrue(eq, "Reference contract balance should be 1 wei after failed migrateTo");
    }
}

contract Rejector {
    receive() external payable {
        revert("I reject Ether");
    }
}

